//! Compact zero-dependency Pinyin lookup for U+4E00..U+9FA5 (20,902 CJK characters).
use base64::Engine;
use std::sync::OnceLock;

const SYLLABLES: &[&str] = &["", "yi", "ding", "kao", "qi", "shang", "xia", "han", "wan", "zhang", "san", "ji", "bu", "yu", "mian", "gai", "chou", "zhuan", "qie", "pi", "shi", "qiu", "bing", "ye", "cong", "dong", "si", "cheng", "diu", "liang", "you", "yan", "sang", "gun", "jiu", "ge", "ya", "qiang", "zhong", "jie", "feng", "guan", "chuan", "chan", "lin", "zhuo", "zhu", "ba", "dan", "wei", "jing", "li", "ju", "pie", "fu", "nai", "wu", "tuo", "me", "zhi", "zha", "hu", "fa", "le", "yin", "ping", "pang", "qiao", "guai", "mie", "xi", "xiang", "shu", "dou", "nang", "jia", "mao", "mai", "luan", "zi", "ru", "xue", "sha", "na", "gan", "suo", "cui", "zhe", "qian", "gui", "jue", "ma", "zheng", "er", "chu", "kui", "yun", "sui", "gen", "xie", "tou", "wang", "kang", "da", "jiao", "hai", "heng", "mu", "ting", "qin", "bo", "lian", "duo", "ren", "shen", "ze", "jin", "pu", "reng", "fo", "lun", "cang", "zai", "ta", "xian", "hong", "tong", "dai", "ling", "chao", "chang", "sa", "men", "fan", "yang", "wo", "jian", "yao", "fen", "di", "fang", "pei", "diao", "dun", "xin", "ai", "xiu", "tang", "huo", "hui", "che", "xun", "nu", "gu", "ni", "ban", "xu", "zhou", "qu", "ci", "beng", "ga", "dian", "bi", "zhao", "zuo", "ti", "zhan", "he", "she", "gou", "ning", "yong", "wa", "ka", "bao", "lao", "bai", "ming", "hen", "quan", "tiao", "xing", "kan", "lai", "chi", "kua", "guang", "mi", "an", "lu", "mou", "cha", "gong", "cun", "lv", "zhen", "ce", "kuai", "chai", "nong", "hou", "jiong", "tui", "nan", "xiao", "bian", "cu", "e", "ku", "jun", "zu", "hun", "su", "lia", "pai", "biao", "fei", "bei", "zong", "tian", "dao", "tan", "chui", "peng", "kong", "juan", "luo", "song", "leng", "ben", "cai", "zhai", "qing", "ying", "ruan", "chun", "ruo", "pian", "sheng", "huang", "duan", "ou", "za", "lou", "sou", "yuan", "rong", "jiang", "bang", "hao", "shan", "bin", "nuo", "can", "lei", "zao", "ao", "chuang", "piao", "man", "zun", "liao", "tie", "seng", "min", "sai", "dang", "xuan", "tai", "lan", "meng", "qiong", "lie", "kuang", "zan", "chen", "teng", "long", "rang", "xiong", "chong", "dui", "ke", "tu", "nei", "liu", "shou", "ran", "gang", "gua", "kou", "pan", "qia", "mei", "zhun", "cou", "du", "kai", "deng", "wen", "hua", "yue", "bie", "pao", "geng", "shua", "cuo", "la", "pou", "tuan", "mo", "keng", "shao", "gao", "lang", "weng", "tao", "nao", "zang", "suan", "nian", "shuai", "ang", "que", "zui", "rou", "shuang", "die", "rui", "po", "mang", "tun", "fou", "shun", "guo", "pen", "ne", "m", "huai", "pin", "ha", "yo", "o", "shuo", "huan", "nou", "ken", "a", "chuai", "pa", "se", "nie", "wai", "miao", "n", "cao", "de", "hei", "ceng", "hm", "ca", "chuo", "zen", "lo", "nin", "kun", "qun", "ri", "lve", "zhui", "hang", "sao", "zeng", "zhuang", "en", "zou", "nv", "nuan", "niu", "rao", "niang", "niao", "nen", "sun", "kuan", "cen", "cuan", "shui", "kuo", "te", "re", "zei", "den", "zhua", "shuan", "zhuai", "rua", "zuan", "shai", "sen", "run", "chua", "nve", "gei", "neng", "fiao", "ei", "miu", "eng", "nun"];
const INDEX_B64: &str = "";

fn table() -> &'static [u16] {
    static TABLE: OnceLock<Vec<u16>> = OnceLock::new();
    TABLE.get_or_init(|| {
        let bytes = base64::engine::general_purpose::STANDARD
            .decode(INDEX_B64)
            .unwrap_or_default();
        bytes
            .chunks_exact(2)
            .map(| pair | u16::from_le_bytes([pair[0], pair[1]]))
            .collect()
    })
}

#[inline]
pub fn char_pinyin(ch: char) -> &'static str {
    let code = ch as u32;
    if !(0x4E00..=0x9FA5).contains(&code) {
        return "";
    }
    let idx = table().get((code - 0x4E00) as usize).copied().unwrap_or(0) as usize;
    SYLLABLES.get(idx).copied().unwrap_or("")
}

/// Matches `text` against an already-lowercased `term` via literal substring OR
/// (when `term` is >= 2 ASCII alphanumeric chars) Pinyin initials / full Pinyin.
pub fn matches_text_or_pinyin(text: &str, lower_term: &str) -> bool {
    if lower_term.is_empty() || text.is_empty() {
        return false;
    }
    if text.to_lowercase().contains(lower_term) {
        return true;
    }
    if lower_term.len() < 2 || !lower_term.bytes().all(|b| b.is_ascii_lowercase() || b.is_ascii_digit()) {
        return false;
    }
    if !text.chars().any(|c| ('\u{4E00}'..'\u{9FA6}').contains(&c)) {
        return false;
    }

    let mut full = String::with_capacity(64);
    let mut initials = String::with_capacity(32);
    for ch in text.chars().take(600) {
        let py = char_pinyin(ch);
        if !py.is_empty() {
            full.push_str(py);
            if let Some(first) = py.chars().next() {
                initials.push(first);
            }
        } else if ch.is_ascii_alphanumeric() {
            let lower = ch.to_ascii_lowercase();
            full.push(lower);
            initials.push(lower);
        }
    }
    initials.contains(lower_term) || full.contains(lower_term)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn matches_initials_and_full_pinyin() {
        assert!(matches_text_or_pinyin("身份证号码 110101", "sfz"));
        assert!(matches_text_or_pinyin("身份证号码", "shenfenzheng"));
        assert!(matches_text_or_pinyin("工作邮箱", "gzyx"));
        assert!(matches_text_or_pinyin("极光剪贴板 AuraClip", "jgjtb"));
        assert!(!matches_text_or_pinyin("/Users/me/screenshot-test.png", "sfz"));
    }
}
